create extension if not exists pgcrypto;
create type public.staff_role as enum ('admin','attendant','kitchen','courier');
create type public.order_status as enum ('new','confirmed','preparing','ready','out_for_delivery','delivered','cancelled');
create table public.restaurants (id uuid primary key default gen_random_uuid(), slug text unique not null, name text not null, logo_url text, whatsapp text not null default '', phone text not null default '', address text not null default '', timezone text not null default 'America/Bahia', active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.profiles (id uuid primary key references auth.users on delete cascade, restaurant_id uuid not null references public.restaurants, name text not null, role public.staff_role not null default 'attendant', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.restaurant_settings (restaurant_id uuid primary key references public.restaurants on delete cascade, minimum_order integer not null default 0 check(minimum_order>=0), pix_key text not null default '', brand_color text not null default '#b6232d' check(brand_color ~ '^#[0-9A-Fa-f]{6}$'), instagram text not null default '', hours jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.categories (id uuid primary key default gen_random_uuid(), restaurant_id uuid not null references public.restaurants on delete cascade, name text not null, active boolean not null default true, sort_order integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(id,restaurant_id));
create table public.products (id uuid primary key default gen_random_uuid(), restaurant_id uuid not null references public.restaurants on delete cascade, category_id uuid not null, name text not null, description text not null default '', image_url text, price integer not null check(price>=0), promotional_price integer check(promotional_price>=0 and promotional_price<=price), active boolean not null default true, featured boolean not null default false, is_pizza boolean not null default false, stock_quantity integer check(stock_quantity>=0), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(id,restaurant_id), foreign key(category_id,restaurant_id) references public.categories(id,restaurant_id));
create table public.product_sizes (id uuid primary key default gen_random_uuid(), product_id uuid not null, restaurant_id uuid not null references public.restaurants, name text not null check(name in ('Pequena','Média','Grande','Família')), price integer not null check(price>=0), active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(product_id,name), foreign key(product_id,restaurant_id) references public.products(id,restaurant_id) on delete cascade);
create table public.addons (id uuid primary key default gen_random_uuid(), restaurant_id uuid not null references public.restaurants on delete cascade, name text not null, price integer not null check(price>=0), kind text not null default 'addon' check(kind in ('addon','crust')), active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.customers (id uuid primary key default gen_random_uuid(), restaurant_id uuid not null references public.restaurants, name text not null, phone text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(restaurant_id,phone), unique(id,restaurant_id));
create table public.customer_addresses (id uuid primary key default gen_random_uuid(), restaurant_id uuid not null references public.restaurants, customer_id uuid not null, address jsonb not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), foreign key(customer_id,restaurant_id) references public.customers(id,restaurant_id));
create table public.coupons (id uuid primary key default gen_random_uuid(), restaurant_id uuid not null references public.restaurants, code text not null check(code=upper(code)), kind text not null check(kind in ('fixed','percent')), value integer not null check(value>0 and (kind<>'percent' or value<=100)), minimum_order integer not null default 0 check(minimum_order>=0), starts_at timestamptz not null, expires_at timestamptz not null, usage_limit integer check(usage_limit>0), used_count integer not null default 0, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(restaurant_id,code), check(expires_at>starts_at));
create table public.delivery_zones (id uuid primary key default gen_random_uuid(), restaurant_id uuid not null references public.restaurants, name text not null, fee integer not null check(fee>=0), estimated_minutes integer not null check(estimated_minutes>0), active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(restaurant_id,name));
create table public.orders (id uuid primary key default gen_random_uuid(), number bigint generated always as identity unique, restaurant_id uuid not null references public.restaurants, customer_id uuid not null, owner_id uuid not null references auth.users, idempotency_key uuid not null, customer_name text not null, customer_phone text not null, address jsonb, fulfillment text not null check(fulfillment in ('delivery','pickup','table')), table_number text, payment text not null check(payment in ('pix','cash','card')), change_for integer, status public.order_status not null default 'new', subtotal integer not null check(subtotal>=0), delivery_fee integer not null check(delivery_fee>=0), discount integer not null check(discount>=0), total integer not null check(total>=0 and total=subtotal+delivery_fee-discount), coupon_id uuid references public.coupons, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(owner_id,idempotency_key), unique(id,restaurant_id), foreign key(customer_id,restaurant_id) references public.customers(id,restaurant_id));
create table public.order_items (id uuid primary key default gen_random_uuid(), order_id uuid not null, restaurant_id uuid not null references public.restaurants, product_id uuid references public.products on delete set null, second_flavor_id uuid references public.products on delete set null, product_name text not null, size_name text, flavor_name text, quantity integer not null check(quantity between 1 and 50), unit_price integer not null check(unit_price>=0), notes text not null default '', addons jsonb not null default '[]', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), foreign key(order_id,restaurant_id) references public.orders(id,restaurant_id) on delete cascade);
create table public.notifications (id uuid primary key default gen_random_uuid(), restaurant_id uuid not null references public.restaurants, order_id uuid not null references public.orders, message text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.order_events (id uuid primary key default gen_random_uuid(), restaurant_id uuid not null references public.restaurants, order_id uuid not null references public.orders, status public.order_status not null, actor_id uuid references auth.users, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index orders_restaurant_created on public.orders(restaurant_id,created_at desc);
create index orders_restaurant_status on public.orders(restaurant_id,status);
create index orders_owner on public.orders(owner_id);
create index orders_customer on public.orders(customer_id,created_at desc);
create index items_order on public.order_items(order_id);
create index events_order on public.order_events(order_id,created_at);
create index products_category on public.products(category_id);
create index profiles_restaurant on public.profiles(restaurant_id);
create function public.staff_access(r uuid, roles public.staff_role[] default array['admin','attendant','kitchen','courier']::public.staff_role[]) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.profiles where id=auth.uid() and restaurant_id=r and role=any(roles))$$;
create function public.touch_updated() returns trigger language plpgsql set search_path='' as $$begin new.updated_at=now();return new;end$$;
do $$declare t text;begin foreach t in array array['restaurants','profiles','restaurant_settings','categories','products','product_sizes','addons','customers','customer_addresses','coupons','delivery_zones','orders','order_items','notifications','order_events'] loop execute format('alter table public.%I enable row level security',t);execute format('create trigger touch before update on public.%I for each row execute function public.touch_updated()',t);end loop;end$$;
create policy restaurant_read on public.restaurants for select using(active or public.staff_access(id));
create policy restaurant_update on public.restaurants for update to authenticated using(public.staff_access(id,array['admin']::public.staff_role[])) with check(public.staff_access(id,array['admin']::public.staff_role[]));
create policy profile_read on public.profiles for select to authenticated using(id=auth.uid() or public.staff_access(restaurant_id,array['admin']::public.staff_role[]));
-- Staff membership is provisioned by an operator, never through self-sign-up or user metadata.
do $$declare t text;begin foreach t in array array['categories','products','product_sizes','addons','delivery_zones'] loop execute format('create policy catalog_read on public.%I for select using ((active and exists(select 1 from public.restaurants r where r.id=restaurant_id and r.active)) or public.staff_access(restaurant_id))',t);execute format('create policy admin_write on public.%I for all to authenticated using(public.staff_access(restaurant_id,array[''admin'']::public.staff_role[])) with check(public.staff_access(restaurant_id,array[''admin'']::public.staff_role[]))',t);execute format('create index on public.%I(restaurant_id)',t);end loop;end$$;
create policy settings_read on public.restaurant_settings for select using(exists(select 1 from public.restaurants r where r.id=restaurant_id and r.active) or public.staff_access(restaurant_id));
create policy settings_write on public.restaurant_settings for all to authenticated using(public.staff_access(restaurant_id,array['admin']::public.staff_role[])) with check(public.staff_access(restaurant_id,array['admin']::public.staff_role[]));
create policy coupon_admin on public.coupons for all to authenticated using(public.staff_access(restaurant_id,array['admin']::public.staff_role[])) with check(public.staff_access(restaurant_id,array['admin']::public.staff_role[]));
do $$declare t text;begin foreach t in array array['customers','customer_addresses'] loop execute format('create policy customer_staff on public.%I for select to authenticated using(public.staff_access(restaurant_id,array[''admin'',''attendant'']::public.staff_role[]))',t);end loop;end$$;
create policy order_read on public.orders for select to authenticated using(owner_id=auth.uid() or public.staff_access(restaurant_id,array['admin','attendant']::public.staff_role[]) or (status in ('confirmed','preparing','ready') and public.staff_access(restaurant_id,array['kitchen']::public.staff_role[])) or (fulfillment='delivery' and status in ('ready','out_for_delivery') and public.staff_access(restaurant_id,array['courier']::public.staff_role[])));
create policy item_read on public.order_items for select to authenticated using(exists(select 1 from public.orders o where o.id=order_id));
create policy event_read on public.order_events for select to authenticated using(exists(select 1 from public.orders o where o.id=order_id));
create policy notification_read on public.notifications for select to authenticated using(public.staff_access(restaurant_id,array['admin','attendant']::public.staff_role[]));
-- No direct customer inserts/updates to orders, totals, stock, coupon usage or events.
create function public.restaurant_open(r uuid) returns boolean language plpgsql stable security definer set search_path='' as $$declare h jsonb; d int; tm text; today jsonb; yesterday jsonb; localtime timestamp;begin select now() at time zone x.timezone,s.hours into localtime,h from public.restaurants x join public.restaurant_settings s on s.restaurant_id=x.id where x.id=r and x.active;if h is null then return false;end if;d=extract(dow from localtime);tm=to_char(localtime,'HH24:MI');today=h->d::text;yesterday=h->((d+6)%7)::text;return coalesce((today->>'enabled')::boolean and (case when today->>'open'<today->>'close' then tm>=today->>'open' and tm<today->>'close' else tm>=today->>'open' end),false) or coalesce((yesterday->>'enabled')::boolean and yesterday->>'open'>=yesterday->>'close' and tm<yesterday->>'close',false);end$$;
create function public.quote_order(r uuid, payload jsonb, consume boolean default false) returns jsonb language plpgsql security definer set search_path='' as $$
declare it jsonb;p public.products;sp public.products;s public.product_sizes;ss public.product_sizes;a public.addons;c public.coupons;cfg public.restaurant_settings;co jsonb=payload->'checkout';line jsonb;lines jsonb='[]';adds jsonb;aid text;qty int;unit int;sub int=0;fee int=0;disc int=0;crust int;begin
 if auth.uid() is null then raise exception 'Entre na sessão para continuar.';end if;
 if not public.restaurant_open(r) then raise exception 'Restaurante fechado.';end if;
 select * into cfg from public.restaurant_settings where restaurant_id=r;
 if jsonb_typeof(payload->'items')<>'array' or jsonb_array_length(payload->'items') not between 1 and 50 then raise exception 'Carrinho inválido.';end if;
 -- Lock products deterministically; serialize stock validation and avoid overselling.
 perform id from public.products where restaurant_id=r and id in (select (value->>'product_id')::uuid from jsonb_array_elements(payload->'items') union select nullif(value->>'second_flavor_id','')::uuid from jsonb_array_elements(payload->'items')) order by id for update;
 for it in select value from jsonb_array_elements(payload->'items') loop
  select * into p from public.products where id=(it->>'product_id')::uuid and restaurant_id=r and active;
  if not found then raise exception 'Produto indisponível.';end if;
  qty=(it->>'quantity')::int;if qty is null or qty not between 1 and 50 or length(coalesce(it->>'notes',''))>500 then raise exception 'Item inválido.';end if;
  s=null;ss=null;sp=null;unit=coalesce(p.promotional_price,p.price);
  if p.is_pizza then
   select * into s from public.product_sizes where id=(it->>'size_id')::uuid and product_id=p.id and active;if not found then raise exception 'Tamanho indisponível.';end if;unit=s.price;
   if nullif(it->>'second_flavor_id','') is not null then select * into sp from public.products where id=(it->>'second_flavor_id')::uuid and restaurant_id=r and is_pizza and active;if not found then raise exception 'Sabor indisponível.';end if;select * into ss from public.product_sizes where product_id=sp.id and name=s.name and active;if not found then raise exception 'Tamanho do segundo sabor indisponível.';end if;unit=greatest(unit,ss.price);end if;
  elsif nullif(it->>'size_id','') is not null or nullif(it->>'second_flavor_id','') is not null then raise exception 'Opções inválidas.';end if;
  if jsonb_typeof(it->'addon_ids')<>'array' or jsonb_array_length(it->'addon_ids')>20 then raise exception 'Adicionais inválidos.';end if;
  if (select count(*)<>count(distinct value) from jsonb_array_elements_text(it->'addon_ids')) then raise exception 'Adicional duplicado.';end if;
  adds='[]';crust=0;for aid in select value from jsonb_array_elements_text(it->'addon_ids') loop select * into a from public.addons where id=aid::uuid and restaurant_id=r and active;if not found then raise exception 'Adicional indisponível.';end if;if a.kind='crust' then crust=crust+1;if not p.is_pizza or crust>1 then raise exception 'Borda inválida.';end if;end if;unit=unit+a.price;adds=adds||jsonb_build_array(jsonb_build_object('name',a.name,'price',a.price));end loop;
  if p.stock_quantity is not null and p.stock_quantity<qty then raise exception 'Estoque insuficiente: %',p.name;end if;
  if sp.id is not null and sp.id<>p.id and sp.stock_quantity is not null and sp.stock_quantity<qty then raise exception 'Estoque insuficiente: %',sp.name;end if;
  -- Even quotes temporarily decrement in their transaction; restore below when consume=false.
  update public.products set stock_quantity=stock_quantity-qty where id=p.id and stock_quantity is not null;
  if sp.id is not null and sp.id<>p.id then update public.products set stock_quantity=stock_quantity-qty where id=sp.id and stock_quantity is not null;end if;
  sub=sub+unit*qty;
  lines=lines||jsonb_build_array(jsonb_build_object('product_id',p.id,'second_flavor_id',case when sp.id<>p.id then sp.id else null end,'product_name',p.name,'size_name',s.name,'flavor_name',sp.name,'quantity',qty,'unit_price',unit,'notes',coalesce(it->>'notes',''),'addons',adds));
 end loop;
 if sub<cfg.minimum_order then raise exception 'Pedido abaixo do valor mínimo.';end if;
 if co->>'fulfillment'='delivery' then select z.fee into fee from public.delivery_zones z where z.restaurant_id=r and z.active and z.name=co->>'neighborhood';if not found then raise exception 'Bairro fora da área de entrega.';end if;elsif co->>'fulfillment' not in ('pickup','table') or co->>'fulfillment' is null then raise exception 'Recebimento inválido.';end if;
 if coalesce(co->>'coupon','')<>'' then select * into c from public.coupons where restaurant_id=r and code=upper(trim(co->>'coupon')) for update;if not found or not c.active or now()<c.starts_at or now()>c.expires_at or (c.usage_limit is not null and c.used_count>=c.usage_limit) or sub<c.minimum_order then raise exception 'Cupom inválido, esgotado ou mínimo não atingido.';end if;disc=least(sub,case when c.kind='percent' then (sub::bigint*c.value/100)::int else c.value end);if consume then update public.coupons set used_count=used_count+1 where id=c.id;end if;end if;
 if not consume then for line in select value from jsonb_array_elements(lines) loop update public.products set stock_quantity=stock_quantity+(line->>'quantity')::int where id=(line->>'product_id')::uuid and stock_quantity is not null;update public.products set stock_quantity=stock_quantity+(line->>'quantity')::int where id=(line->>'second_flavor_id')::uuid and stock_quantity is not null;end loop;end if;
 return jsonb_build_object('items',lines,'subtotal',sub,'delivery_fee',fee,'discount',disc,'total',sub+fee-disc,'coupon_id',c.id);
end$$;
-- Internal routine cannot be called directly, including consume=true.
revoke all on function public.quote_order(uuid,jsonb,boolean) from public,anon,authenticated;
create function public.preview_order(r uuid,payload jsonb) returns jsonb language plpgsql security definer set search_path='' as $$begin return public.quote_order(r,payload,false);end$$;
create function public.create_order(r uuid,payload jsonb) returns uuid language plpgsql security definer set search_path='' as $$
declare existing uuid;uid uuid=auth.uid();co jsonb=payload->'checkout';q jsonb;cust uuid;oid uuid;ln jsonb;addr jsonb;changeval int;k uuid=(payload->>'idempotency_key')::uuid;begin
 if uid is null or k is null then raise exception 'Sessão inválida.';end if;
 perform pg_advisory_xact_lock(hashtextextended(uid::text,0));
 select id into existing from public.orders where owner_id=uid and idempotency_key=k;if found then return existing;end if;
 if (select count(*) from public.orders where owner_id=uid and created_at>now()-interval '10 minutes')>=5 then raise exception 'Aguarde antes de criar outro pedido.';end if;
 if length(trim(co->>'name')) not between 3 and 120 or co->>'name' is null or co->>'phone' is null or co->>'phone' !~ '^\d{10,13}$' or co->>'payment' is null or co->>'payment' not in ('pix','cash','card') then raise exception 'Dados do cliente inválidos.';end if;
 if co->>'fulfillment'='delivery' then
  if co->>'cep' is null or co->>'cep' !~ '^\d{5}-?\d{3}$' or co->>'state' is null or co->>'state' !~ '^[A-Z]{2}$' then raise exception 'CEP ou estado inválido.';end if;
  if exists(select 1 from unnest(array['street','number','neighborhood','complement','city','reference']) field where length(trim(coalesce(co->>field,''))) not between 1 and 200) then raise exception 'Endereço incompleto.';end if;
  addr=jsonb_build_object('CEP',co->>'cep','Rua',co->>'street','Número',co->>'number','Bairro',co->>'neighborhood','Complemento',co->>'complement','Cidade',co->>'city','UF',co->>'state','Referência',co->>'reference');
 end if;
 if co->>'fulfillment'='table' and (co->>'table_number' is null or co->>'table_number' !~ '^\d{1,4}$') then raise exception 'Mesa inválida.';end if;
 q=public.quote_order(r,payload,true);
 if co->>'payment'='cash' and coalesce(co->>'change_for','')<>'' then changeval=round(replace(co->>'change_for',',','.')::numeric*100);if changeval<(q->>'total')::int then raise exception 'Troco menor que o total.';end if;end if;
 insert into public.customers(restaurant_id,name,phone) values(r,trim(co->>'name'),co->>'phone') on conflict(restaurant_id,phone) do update set name=excluded.name returning id into cust;
 if addr is not null then insert into public.customer_addresses(restaurant_id,customer_id,address) values(r,cust,addr);end if;
 insert into public.orders(restaurant_id,customer_id,owner_id,idempotency_key,customer_name,customer_phone,address,fulfillment,table_number,payment,change_for,subtotal,delivery_fee,discount,total,coupon_id) values(r,cust,uid,k,trim(co->>'name'),co->>'phone',addr,co->>'fulfillment',case when co->>'fulfillment'='table' then co->>'table_number' end,co->>'payment',changeval,(q->>'subtotal')::int,(q->>'delivery_fee')::int,(q->>'discount')::int,(q->>'total')::int,(q->>'coupon_id')::uuid) returning id into oid;
 for ln in select value from jsonb_array_elements(q->'items') loop insert into public.order_items(order_id,restaurant_id,product_id,second_flavor_id,product_name,size_name,flavor_name,quantity,unit_price,notes,addons) values(oid,r,(ln->>'product_id')::uuid,(ln->>'second_flavor_id')::uuid,ln->>'product_name',ln->>'size_name',ln->>'flavor_name',(ln->>'quantity')::int,(ln->>'unit_price')::int,ln->>'notes',ln->'addons');end loop;
 insert into public.notifications(restaurant_id,order_id,message) values(r,oid,'Novo pedido recebido');insert into public.order_events(restaurant_id,order_id,status,actor_id) values(r,oid,'new',uid);return oid;
end$$;
create function public.change_order_status(oid uuid,target public.order_status) returns void language plpgsql security definer set search_path='' as $$declare o public.orders;role public.staff_role;i public.order_items;begin
 select * into o from public.orders where id=oid for update;if not found then raise exception 'Pedido não encontrado.';end if;
 select p.role into role from public.profiles p where p.id=auth.uid() and p.restaurant_id=o.restaurant_id;if role is null then raise exception 'Acesso negado.';end if;
 if role='kitchen' and not(o.status in ('confirmed','preparing') and target in ('preparing','ready')) then raise exception 'Acesso negado.';end if;
 if role='courier' and not(o.fulfillment='delivery' and o.status in ('ready','out_for_delivery') and target in ('out_for_delivery','delivered')) then raise exception 'Acesso negado.';end if;
 if not ((o.status='new' and target='confirmed') or (o.status='confirmed' and target='preparing') or (o.status='preparing' and target='ready') or (o.status='ready' and ((o.fulfillment='delivery' and target='out_for_delivery') or (o.fulfillment<>'delivery' and target='delivered'))) or (o.status='out_for_delivery' and target='delivered') or (target='cancelled' and o.status not in ('delivered','cancelled') and role in ('admin','attendant'))) then raise exception 'Transição de status inválida.';end if;
 if target='cancelled' then for i in select * from public.order_items where order_id=oid loop update public.products set stock_quantity=stock_quantity+i.quantity where id=i.product_id and stock_quantity is not null;update public.products set stock_quantity=stock_quantity+i.quantity where id=i.second_flavor_id and stock_quantity is not null;end loop;if o.coupon_id is not null then update public.coupons set used_count=greatest(0,used_count-1) where id=o.coupon_id;end if;end if;
 update public.orders set status=target where id=oid;insert into public.order_events(restaurant_id,order_id,status,actor_id) values(o.restaurant_id,oid,target,auth.uid());end$$;
revoke all on function public.preview_order(uuid,jsonb),public.create_order(uuid,jsonb),public.change_order_status(uuid,public.order_status) from public,anon;
grant execute on function public.preview_order(uuid,jsonb),public.create_order(uuid,jsonb),public.change_order_status(uuid,public.order_status) to authenticated;
alter publication supabase_realtime add table public.orders,public.notifications,public.order_events;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('restaurant-images','restaurant-images',true,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create policy image_read on storage.objects for select using(bucket_id='restaurant-images');
create policy image_admin on storage.objects for insert to authenticated with check(bucket_id='restaurant-images' and public.staff_access((storage.foldername(name))[1]::uuid,array['admin']::public.staff_role[]));
create policy image_delete on storage.objects for delete to authenticated using(bucket_id='restaurant-images' and public.staff_access((storage.foldername(name))[1]::uuid,array['admin']::public.staff_role[]));
